def convert_roles(apps, schema_editor):
    """Bisherige Rollen in Rechte pro Bereich umsetzen: Bediener -> Schalten, Leser -> Sehen (Admin bleibt)."""
    User = apps.get_model('auth', 'User')
    Group = apps.get_model('auth', 'Group')
    Grant = apps.get_model('heating', 'Grant')
    Point = apps.get_model('heating', 'Point')
    for user in User.objects.all():
        names = set(user.groups.values_list('name', flat=True))
        level = 'control' if 'operator' in names else ('view' if 'reader' in names else '')
        if level and 'admin' not in names:
            for section in SECTIONS:
                Grant.objects.get_or_create(user=user, section=section, defaults={'level': level})
    Group.objects.filter(name__in=['operator', 'reader']).delete()
    Point.objects.filter(key__in=CRITICAL).update(confirm=True)


